 * 那是整份设计文档可执行性的证据。样张里有两处**不是编译产物**的行（见下方 `GOLDEN_LINES`
 * 的注释），以及一处路径前缀省略与一处 ⑤ 段占位符，对齐方式见各自的注释。
 */

import { describe, expect, it } from 'vitest'
import { analyzeGraph } from '../../src/shared/graph.ts'
