/** 屏幕中心（新节点落在你正看着的地方）。 */
function centerOf(flow: ReactFlowInstance<FlowNode, FlowEdge>): { x: number; y: number } {
  const bounds = flow.getViewport()
  const width = flow.container?.getBoundingClientRect().width ?? 600
  const height = flow.container?.getBoundingClientRect().height ?? 400
  // 反投影：viewport 的 (x,y) 是平移量，(width/2 - x) / zoom 才是画布坐标。
  return { x: (width / 2 - bounds.x) / bounds.zoom, y: (height / 2 - bounds.y) / bounds.zoom }
}

/** 状态点的语气类。 */
function statusTone(state: CanvasState): string {
  if (state.blocked || state.status === 'error') return css.statusError
  if (state.status === 'saving' || state.status === 'loading') return css.statusBusy
  if (state.dirty) return css.statusDirty
  if (state.status === 'saved' || state.status === 'idle') return css.statusOk
  return ''
}

