/** 一条边的列表组。 */
function EdgeList(props: {
  t: Translate
  views: readonly EdgeView[]
  onSetWhen: (view: EdgeView, to: string) => void
  onDisconnect: (view: EdgeView) => void
  onSelect: (node: string) => void
}): React.JSX.Element {
  if (props.views.length === 0) return <p className={css.muted}>{props.t('panel.noEdges')}</p>
  return (
    <ul className={css.edgeList}>
      {props.views.map((view) => (
        <li key={`${view.edge.id}|${view.other}`}>
          <EdgeRow
            t={props.t}
            view={view}
            onSetWhen={props.onSetWhen}
            onDisconnect={props.onDisconnect}
            onSelect={props.onSelect}
          />
        </li>
      ))}
    </ul>
  )
}

/**
 * 一行边：另一端 + `when` 输入 + 断开。
 *
 * `when` 用**本地草稿**：非法值（含空格的自由文本、超长）不提交，只标红——
 * 提交一个非法的 `when` 会写出**保存级破损**的图，那是把画布自己锁死。
 */
function EdgeRow(props: {
  t: Translate
  view: EdgeView
  onSetWhen: (view: EdgeView, to: string) => void
  onDisconnect: (view: EdgeView) => void
  onSelect: (node: string) => void
}): React.JSX.Element {
  const committed = props.view.edge.data?.when ?? ''
  const [draft, setDraft] = useState(committed)
  useEffect(() => {
    setDraft(committed)
  }, [committed])
  const problem = draft === '' ? null : checkWhen(draft)
  const invalid = problem !== null

  return (
    <div className={[css.edgeRow, props.view.back ? css.edgeRowBack : ''].join(' ')}>
      <button
        type="button"
        className={css.edgeName}
        title={props.view.other}
        onClick={() => props.onSelect(props.view.other)}
      >
        {props.view.other}
      </button>
      <input
        className={[css.input, css.edgeWhen].join(' ')}
        list="workflow-lite-when"
        value={draft}
        placeholder={props.t('panel.whenNone')}
        title={invalid ? problem.message : props.t('panel.when')}
        onChange={(event) => {
          const value = event.target.value
          setDraft(value)
          if (value === '' || checkWhen(value) === null) props.onSetWhen(props.view, value)
        }}
        onBlur={() => {
          if (invalid) setDraft(committed)
        }}
      />
      {props.view.back && <span className={css.tagBack}>{props.t('panel.edgeBack')}</span>}
      <button
        type="button"
        className={[css.button, css.buttonDanger].join(' ')}
        title={props.t('canvas.deleteEdge')}
        onClick={() => props.onDisconnect(props.view)}
      >
        ×
      </button>
    </div>
  )
}

