/**
 * URL path prefix the gateway itself is served under ("" for the site root).
 *
 * A host that embeds this gateway in-process (`theirApp.route("/pi", gateway.app)`)
 * does not need this: mounting already prefixes every route. It exists for a
 * standalone `pi-gateway --base-path /pi` deployment, where requests arrive at
 * the process with the prefix attached.
 */

/** Allowed shape of a single prefix segment; excludes ".", ".." and %-escapes. */
const SEGMENT_RE = /^[A-Za-z0-9._~-]+$/;

/**
 * Normalize a user-supplied prefix to "" or "/segment[/segment...]".
 *
 * Accepts "pi", "/pi", "/pi/" and rejects anything that can escape the prefix
 * or smuggle a query/fragment ("..", "//", "?", "#", "%").
 */
export function normalizeBasePath(raw: string | undefined | null): string {
	const trimmed = (raw ?? "").trim();
	if (trimmed === "" || trimmed === "/") return "";

	const withLeadingSlash = trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
	const withoutTrailingSlash = withLeadingSlash.replace(/\/+$/, "");
	if (withoutTrailingSlash === "") return "";

	const segments = withoutTrailingSlash.split("/").slice(1);
	for (const segment of segments) {
		if (!SEGMENT_RE.test(segment)) {
			throw new Error(
				`Invalid base path ${JSON.stringify(raw)}: segment ${JSON.stringify(segment)} is not allowed`,
			);
		}
	}
	return withoutTrailingSlash;
}

/** Escape a literal string for use inside a RegExp. */
export function escapeRegExp(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

