/**
 * Drop every active session owned by an agent, so the next prompt reopens
 * it from disk and re-reads the profile (identity files + tool allowlist).
 *
 * This is how a profile edit — an expert bind or clear, a capabilities
 * patch, an edited `default.md` — reaches a session that is already
 * running. A session that is not active is already reading the new profile
 * on its next open, so it is left alone. Returns how many were dropped.
 *
 * Sessions with no file on disk are left alone too: pi writes a session
 * file on the first assistant message, so a session that was created but
 * never answered has nothing persisted to reopen from — dropping it would
 * destroy it rather than rebuild it. It carries no conversation yet, so
 * the profile it read at create time is the only thing it can serve.
 */
async rebuildSessions(agentId: string): Promise<number> {
	const ids = await this.store.getSessionIdsByAgent(agentId);
	let rebuilt = 0;
	for (const sessionId of ids) {
		if (!this.baseSessions.getActiveSession(sessionId)) continue;
		if (!this.baseSessions.hasPersistedSession(sessionId)) continue;
		await this.baseSessions.unbindSession(sessionId);
		rebuilt += 1;
	}
	return rebuilt;
}

