		// can also be (re)opened later — idle eviction, a gateway restart, or a
		// context rebuild — and those paths carry no options.
		baseSessions.setSessionOpenOverridesResolver(async (sessionId) => {
			const agentId = await this.store.getAgentIdBySession(sessionId);
			if (!agentId) return undefined;
			return this.openOverridesFor(agentId);
		});
	}

	/** Resource-loader overrides + tool allowlist derived from an agent profile. */
	private openOverridesFor(agentId: string): import("../session.ts").SessionOpenOverrides {
		const profile = getAgentProfile(agentId);
		if (!profile) return {};
		return {
			loaderOptions: {
				// Re-read on every load: the profile's `default.md` is rewritten
				// when an expert is bound (or cleared), so the identity must not
				// be a session-create snapshot.
				appendSystemPromptOverride: (base) => {
					const reads = loadDefaultReads(profile);
					return reads ? [...base, reads] : base;
				},
			},
			// "*" wildcard = all tools (undefined); an empty list stays empty.
			toolNames: profile.tools?.includes("*") ? undefined : profile.tools,
		};
	}

	/**
	 * Create a new session using an agent profile.
	 *
	 * @param workspace  The working directory for the session. Falls back to profile.workspace.
	 * @param agentId    Agent profile id from agent-config.json.
	 * @param opts       Optional overrides (title, model).
	 */
	async create(
		workspace: string | undefined,
		agentId: string,
		opts?: AgentSessionOptions,
	): Promise<AgentSessionRecord> {
		const profile = getAgentProfile(agentId);
		if (!profile) {
			throw new Error(`Agent profile not found: ${agentId}`);
		}

		const explicit = typeof workspace === "string" ? workspace.trim() : "";
		const sessionWorkspace = explicit.length > 0 ? explicit : resolveAgentWorkspace(profile);
		mkdirSync(sessionWorkspace, { recursive: true });
		if (explicit.length === 0 && isBlankWorkspace(profile.workspace)) {
			persistAgentWorkspaceIfBlank(agentId, sessionWorkspace);
		}

		// Resolve model: explicit opts override profile model
		const model = opts?.model ?? profile.model;
		// Resolve thinking level: explicit opts override profile thinking
		const thinkingLevel = opts?.thinkingLevel ?? profile.thinking;

		// "*" wildcard = all tools (pass undefined; BaseSessionManager treats undefined as all tools)
		const toolNames = profile.tools?.includes("*") ? undefined : (profile.tools ?? []);

		// Build skills override: filter to only profile.skill names (if specified)
		let skillsOverride: CreateSessionOptions["skillsOverride"];
		{
			const allowed = new Set(profile.skill ?? []);
			// "*" wildcard = all skills (no override → loader default includes everything)
			if (!allowed.has("*")) {
				skillsOverride = (base: { skills: Skill[]; diagnostics: ResourceDiagnostic[] }) => ({
					skills: base.skills.filter((s) => allowed.has(s.name)),
					diagnostics: base.diagnostics,
				});
			}
		}

		// When using an agent prompt, keep the default system prompt and append the agent
		// prompt to it. Replacing the whole prompt (systemPromptOverride) drops the
		// `Available tools` / `Guidelines` sections that extension tools declare via
		// promptSnippet / promptGuidelines. The same overrides are re-applied whenever
		// this session is reopened from disk (see the constructor).
		const openOverrides = this.openOverridesFor(agentId);

		const result: SessionInfoResponse = await this.baseSessions.create(sessionWorkspace, {
			title: opts?.title,
			parentSessionId: opts?.parentSessionId,
			model,
			thinkingLevel,
			toolNames,
			skillsOverride,
			appendSystemPromptOverride: openOverrides.loaderOptions?.appendSystemPromptOverride,
			skipBind: true,
			ircDisplayName: opts?.ircDisplayName ?? profile.id,
		});

		// Write agent→session mapping before extensions fire session_start
		const sid = result.id;
		await this.addSessionMapping(agentId, sid);

		// Now activate — extensions load, session_start fires, agentId is resolvable
		await this.baseSessions.activate(sid);

		return {
			id: sid,
			workspace: sessionWorkspace,
			agentId,
			title: result.title,
			createdAt: result.createdAt,
			updatedAt: result.updatedAt,
		};
	}

	/** Get all session records for a given agent name. */
	async getSessionsByAgent(agentId: string, opts?: { hideSubSessions?: boolean }): Promise<AgentSessionRecord[]> {
		const ids = await this.store.getSessionIdsByAgent(agentId);
		const idSet = new Set(ids);
		const index = await this.baseSessions.refreshSessions();
		const results: AgentSessionRecord[] = [];
		for (const [id, info] of index) {
			if (!idSet.has(id)) continue;
			if (opts?.hideSubSessions && (info.parentSessionId || isAuxiliaryTitle(info.title))) continue;
			results.push({
				id,
				workspace: info.cwd,
				agentId,
				title: info.title,
				createdAt: info.createdAt,
				updatedAt: info.updatedAt,
				parentSessionId: info.parentSessionId,
			});
		}
		results.sort((a, b) => (b.updatedAt || b.createdAt) - (a.updatedAt || a.createdAt) || a.id.localeCompare(b.id));
		return results;
	}

	/** Get all agent session records across all agents. */
	async getAgentSessions(opts?: { hideSubSessions?: boolean }): Promise<AgentSessionRecord[]> {
		const mappings = await this.store.getAllMappings();
		const index = await this.baseSessions.refreshSessions();
		const records: AgentSessionRecord[] = [];
		for (const [agentId, sessionIds] of mappings) {
			for (const sid of sessionIds) {
				const info = index.get(sid);
				if (!info) continue;
				if (opts?.hideSubSessions && (info.parentSessionId || isAuxiliaryTitle(info.title))) continue;
				records.push({
					id: sid,
					workspace: info.cwd,
					agentId,
					title: info.title,
					createdAt: info.createdAt,
					updatedAt: info.updatedAt,
					parentSessionId: info.parentSessionId,
				});
			}
		}
		return records;
	}

	/** Reverse-lookup agent ID by session ID. */
	async getAgentIdBySession(sessionId: string): Promise<string | undefined> {
		return this.store.getAgentIdBySession(sessionId);
	}

	/**
	 * Drop every active session owned by an agent, so the next prompt reopens
	 * it from disk and re-reads the profile (identity files + tool allowlist).
	 *
	 * This is how a profile edit — an expert bind or clear, a capabilities
	 * patch, an edited `default.md` — reaches a session that is already
	 * running. A session that is not active is already reading the new profile
	 * on its next open, so it is left alone. Returns how many were dropped.
	 *
	 * Sessions with no file on disk are left alone too: pi writes a session
	 * file on the first assistant message, so a session that was created but
	 * never answered has nothing persisted to reopen from — dropping it would
	 * destroy it rather than rebuild it. It carries no conversation yet, so it
	 * cannot have missed anything the profile governs.
	 */
	async rebuildSessions(agentId: string): Promise<number> {
		const ids = await this.store.getSessionIdsByAgent(agentId);
		let rebuilt = 0;
		for (const sessionId of ids) {
			if (!this.baseSessions.getActiveSession(sessionId)) continue;
			if (!this.baseSessions.hasPersistedSession(sessionId)) continue;
			await this.baseSessions.unbindSession(sessionId);
			rebuilt += 1;
		}
		return rebuilt;
	}

	// -----------------------------------------------------------------------
	// Delegated session operations (via BaseSessionManager)
	// -----------------------------------------------------------------------

	async get(sessionId: string): Promise<SessionDetailResponse | null> {
		return this.baseSessions.get(sessionId);
	}

	getState(sessionId: string): SessionRuntimeState {
		return this.baseSessions.getState(sessionId);
	}

	async delete(sessionId: string): Promise<void> {
		await this.store.removeSession(sessionId);
		await this.baseSessions.delete(sessionId);
	}

	async rename(sessionId: string, name: string): Promise<void> {
		await this.baseSessions.rename(sessionId, name);
	}
	async getCommands(sessionId: string) {
		return this.baseSessions.getCommands(sessionId);
	}

	async prompt(sessionId: string, content: string, opts?: PromptOptions): Promise<PromptResponse | undefined> {
		return this.baseSessions.prompt(sessionId, content, opts);
	}

	async abort(sessionId: string): Promise<void> {
		await this.baseSessions.abort(sessionId);
	}

	async compact(sessionId: string, customInstructions?: string): Promise<void> {
		await this.baseSessions.compact(sessionId, customInstructions);
	}

	/** Replace the whole context with one summary message (laifpaw `/new` rotate). */
	async replaceContext(
		sessionId: string,
		summary: string,
		opts?: { tokensBefore?: number; details?: unknown },
	): Promise<{ entryId: string; messageCount: number }> {
		return await this.baseSessions.replaceContext(sessionId, summary, opts);
	}

	async invokeTool(
		sessionId: string,
		toolName: string,
		params: unknown,
	): Promise<{ content: unknown[]; details: unknown }> {
		const located =
			toolName === "lsp" && !this.baseSessions.getActiveSession(sessionId)
				? await locatePiSessionFile(sessionId)
				: null;
		return this.baseSessions.invokeTool(sessionId, toolName, params, located ? { cwd: located.cwd } : undefined);
	}

	/**
	 * The tool names an agent session offers on its next turn.
	 *
	 * A loaded session answers from memory. An unloaded one is answered the way
	 * a reopen would resolve it, without reopening: the agent-status
	 * capabilities snapshot clipped to the profile allowlist, else the
	 * allowlist itself. `null` means every tool the gateway registers (a "*"
	 * profile with no snapshot yet).
	 *
	 * Throws when the session is unknown or belongs to another agent.
	 *
	 * PLUGIN-COUPLING(agent-status) — do NOT copy this pattern. Core should not
	 * depend on a plugin's private data. This method does because the unloaded
	 * path must predict what the agent-status plugin restores on reopen (its
	 * `agent_status:capabilities` session entries), and only that plugin knows:
	 * a registration hook cannot work (plugin factories run per loaded session,
	 * so nothing is registered for an unloaded one), and reopening the session
	 * just to ask would have side effects. If agent-status changes its snapshot
	 * format or restore rule, this method must change with it.
	 */
	async getActiveToolNamesCoupledToAgentStatusPlugin(agentId: string, sessionId: string): Promise<string[] | null> {
		const owner = await this.store.getAgentIdBySession(sessionId);
		if (!owner || owner.toLowerCase() !== agentId.toLowerCase()) {
			throw new Error(`Agent session not found: ${sessionId}`);
		}
		const live = this.baseSessions.getActiveSession(sessionId);
		if (live) return live.getActiveToolNames();

		const ceiling = this.openOverridesFor(owner).toolNames;
		const detail = await this.baseSessions.get(sessionId);
		// PLUGIN-COUPLING(agent-status): the plugin's snapshot, read directly.
		const snapshot = detail ? findLatestCapabilitiesSnapshot(detail.entries as SessionEntry[]) : undefined;
		if (!snapshot) return ceiling ?? null;
		if (!ceiling) return snapshot.toolNames;
		const allowed = new Set(ceiling);
		return snapshot.toolNames.filter((name) => allowed.has(name));
	}

	getSessionSelection(sessionId: string): { skillNames: string[]; toolNames: string[] } {
		return this.baseSessions.getSessionSelection(sessionId);
	}

	setSessionSelection(sessionId: string, sel: { skillNames: string[]; toolNames: string[] }): void {
		this.baseSessions.setSessionSelection(sessionId, sel);
	}

	// -----------------------------------------------------------------------
	// Internal helpers
	// -----------------------------------------------------------------------

	private async addSessionMapping(agentId: string, sessionId: string): Promise<void> {
		await this.store.addMapping(agentId, sessionId);
	}
}

