import '@testing-library/jest-dom/vitest';
import i18n from '@/shared/i18n/i18n';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { ModelAccessApplyModal } from '../ModelAccessApplyModal';

/** 收集真正写进剪贴板的内容。给 mock 声明入参类型，否则 mock.calls 会被推断成空元组。 */
const copied: string[] = [];
const clipboardWriteText = vi.fn(async (text: string) => {
  copied.push(text);
});

beforeEach(() => {
  vi.clearAllMocks();
  copied.length = 0;
  // 同 AccountMenu.test.tsx：中文断言依赖这里显式切语言。
  void i18n.changeLanguage('zh');
  Object.assign(navigator, { clipboard: { writeText: clipboardWriteText } });
});

afterEach(() => {
  delete window.desktopWindow;
});

/** 装一个指定结果的桌面桥。 */
function bridge(result: { ok: boolean; error?: string }) {
  window.desktopWindow = {
    isDesktop: true,
    applyInternetModelAccess: vi.fn(async () => result),
  } as unknown as DesktopWindowBridge;
}

/** 填完两步并提交，等到第二步出现。 */
async function renderReady() {
  bridge({ ok: true });
  render(<ModelAccessApplyModal open onOpenChange={() => {}} />);
  fireEvent.change(screen.getByLabelText('工号：'), { target: { value: '15295' } });
  fireEvent.change(screen.getByLabelText('密码：'), { target: { value: 'pw' } });
  fireEvent.click(screen.getByRole('button', { name: '验证并打开申请单' }));
  await waitFor(() => expect(screen.getByText('办公')).toBeInTheDocument());
}

describe('ModelAccessApplyModal', () => {
  it('第一步：字段有可见标签，footer 是取消加主操作', () => {
    render(<ModelAccessApplyModal open onOpenChange={() => {}} />);

    expect(screen.getByLabelText('工号：')).toBeInTheDocument();
    expect(screen.getByLabelText('密码：')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: '取消' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: '验证并打开申请单' })).toBeInTheDocument();
    // 密码可见性按钮自己解释自己。
    expect(screen.getByRole('button', { name: '显示密码' })).toBeInTheDocument();
  });

  it('提示讲的是后果，不是告警：文案里没有破折号', () => {
    render(<ModelAccessApplyModal open onOpenChange={() => {}} />);

    expect(screen.getByText('验证会占用该账号的 OA 会话，可能把已登录的浏览器挤下线。')).toBeInTheDocument();

    // 回归守卫：界面文案不许出现破折号（中文破折号与单个 em dash 都算）。
    const text = document.body.textContent ?? '';
    expect(text).not.toContain('——');
    expect(text).not.toContain('—');
  });

  it('第二步同样没有破折号', async () => {
    await renderReady();

    const text = document.body.textContent ?? '';
    expect(text).not.toContain('——');
    expect(text).not.toContain('—');
  });

  it('验证成功后切到第二步：三步骤逐条在位，且只有三步', async () => {
    await renderReady();

    expect(screen.getByText('1. 下载附件《承诺书》，打印并签署')).toBeInTheDocument();
    expect(screen.getByText('2. 把签署后的承诺书作为附件上传')).toBeInTheDocument();
    expect(screen.getByText('3. 填写「推荐需求/用途」')).toBeInTheDocument();
    expect(screen.getAllByRole('listitem')).toHaveLength(3);
    expect(screen.getByText('编程开发')).toBeInTheDocument();
  });

  it('点复制会把模板正文写进剪贴板', async () => {
    await renderReady();

    fireEvent.click(screen.getAllByRole('button', { name: '复制' })[0]);

    await waitFor(() => expect(copied).toHaveLength(1));
    expect(copied[0]).toContain('非涉密的日常办公文档处理');
  });

  it('第二步只留「关闭」，点它会请求关窗', async () => {
    const onOpenChange = vi.fn();
    bridge({ ok: true });
    render(<ModelAccessApplyModal open onOpenChange={onOpenChange} />);
    fireEvent.change(screen.getByLabelText('工号：'), { target: { value: '15295' } });
    fireEvent.change(screen.getByLabelText('密码：'), { target: { value: 'pw' } });
    fireEvent.click(screen.getByRole('button', { name: '验证并打开申请单' }));

    await waitFor(() => expect(screen.getByText('办公')).toBeInTheDocument());
    expect(screen.queryByRole('button', { name: '验证并打开申请单' })).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole('button', { name: '关闭' }));
    expect(onOpenChange).toHaveBeenCalledWith(false);
  });

  it('关掉再打开会回到干净的初始态（旧的错误与输入都清掉）', async () => {
    bridge({ ok: false, error: '工号或密码错误' });
    const { rerender } = render(<ModelAccessApplyModal open onOpenChange={() => {}} />);
    fireEvent.change(screen.getByLabelText('工号：'), { target: { value: '15295' } });
    fireEvent.change(screen.getByLabelText('密码：'), { target: { value: 'bad' } });
    fireEvent.click(screen.getByRole('button', { name: '验证并打开申请单' }));
    await waitFor(() => expect(screen.getByRole('alert')).toHaveTextContent('工号或密码错误'));

    rerender(<ModelAccessApplyModal open={false} onOpenChange={() => {}} />);
    rerender(<ModelAccessApplyModal open onOpenChange={() => {}} />);

    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
    expect(screen.getByLabelText('工号：')).toHaveValue('');
    expect(screen.getByLabelText('密码：')).toHaveValue('');
  });

  it('失败时留在第一步并展示主进程给的文案', async () => {
    bridge({ ok: false, error: '工号或密码错误' });
    render(<ModelAccessApplyModal open onOpenChange={() => {}} />);
    fireEvent.change(screen.getByLabelText('工号：'), { target: { value: '15295' } });
    fireEvent.change(screen.getByLabelText('密码：'), { target: { value: 'bad' } });
    fireEvent.click(screen.getByRole('button', { name: '验证并打开申请单' }));

    await waitFor(() => expect(screen.getByRole('alert')).toHaveTextContent('工号或密码错误'));
    expect(screen.getByLabelText('工号：')).toBeInTheDocument();
  });
});

