    /// inventory names (falling back to the fixed defaults), web-search its
    /// constant names unioned with live-inventory extras (see
    /// [`web_search_seed`]). Ignored when disabled — a disabled service is
    /// always stripped by prefix.
    pub seed: Vec<String>,
}

/// The knowledge service ceiling with an explicit seed: the live gateway
/// inventory's knowledge tools, or the fixed default names when discovery
/// failed. The default fallback keeps an enabled service usable before the
/// gateway has cached the server.
pub fn knowledge_ceiling_with_seed(enabled: bool, seed: Vec<String>) -> ServiceToolCeiling {
    ServiceToolCeiling {
        prefix: knowledge_tool_prefix(),
        enabled,
        seed,
    }
}

/// The knowledge service ceiling without a live inventory: the four fixed
/// default tool names. Production callers that have the gateway inventory
/// use [knowledge_ceiling_with_seed] instead.
pub fn knowledge_ceiling(enabled: bool) -> ServiceToolCeiling {
    knowledge_ceiling_with_seed(enabled, knowledge_gateway_tool_names())
}

/// The web-search service ceiling: the constant tool names unioned with
/// live-inventory extras (see [`web_search_seed`]); the caller passes an
/// empty seed portion only by convention — strip-only happens through
/// `enabled: false`, not through an empty seed.
pub fn web_search_ceiling(enabled: bool, seed: Vec<String>) -> ServiceToolCeiling {
    ServiceToolCeiling {
        prefix: web_search_tool_prefix(),
        enabled,
        seed,
    }
}

/// The web-search seed: the service's constant tool names first, then any
/// `web_search_`-prefixed inventory extras (future server-side tools) the
/// constants do not cover. Hidden builtins share the prefix shape
/// (`web_search_config` matches it literally) and are never seeded. Correct
/// at any moment: an empty or unreadable inventory still yields the
/// constants, so convergence never waits on the remote MCP or the gateway's
/// tool cache.
pub(crate) fn web_search_seed(inventory: &[String]) -> Vec<String> {
    let mut seed = web_search_gateway_tool_names();
    let prefix = web_search_tool_prefix();
    for name in inventory {
        if name.starts_with(&prefix) && !is_assistant_hidden_builtin_tool(name) && !seed.contains(name) {
            seed.push(name.clone());
        }
    }
    seed
}

/// The gateway's live tool inventory (names only), the same read
/// `seed_default_assistant` performs.
pub(crate) async fn gateway_tool_names(client: &GatewayClient) -> Result<Vec<String>, GatewayError> {
    let tools = client.get_json("/api/tools").await?;
    Ok(tools
        .as_array()
        .map(|list| {
            list.iter()
                .filter_map(|tool| tool.get("name").and_then(Value::as_str))
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default())
}

/// Build the ceilings for every service-linked MCP row currently in the
/// Build the ceilings for every service-linked MCP row currently in the
/// repository: knowledge seeds the live gateway inventory's names (falling
/// back to the fixed defaults when discovery finds nothing), other services
/// seed their constant tool names unioned with the live inventory's extras
/// under their own prefix. Rows are re-read on every call so a pass sees the
/// current state, never a snapshot.
pub(crate) async fn service_tool_ceilings(
    client: &GatewayClient,
    repo: &dyn aionui_db::IMcpServerRepository,
) -> Result<Vec<ServiceToolCeiling>, GatewayError> {
    let rows = repo
        .list()
        .await
        .map_err(|error| GatewayError::Upstream(error.to_string()))?;
    let (inventory, inventory_read) = match gateway_tool_names(client).await {
        Ok(names) => (names, true),
        Err(error) => {
            tracing::warn!(
                error = %error,
                "gateway tool inventory read failed; web-search seeds degrade to their constants and knowledge falls back to the default names"
            );
            (Vec::new(), false)
        }
    };
    let mut ceilings = Vec::new();
    for row in rows.iter().filter(|row| is_service_linked_role(row.role.as_deref())) {
        if row.role.as_deref() == Some(KNOWLEDGE_MCP_ROLE) {
            let seed = if row.enabled {
                let discovered = knowledge_gateway_tools_from_inventory(&inventory);
                if discovered.is_empty() {
                    if inventory_read {
                        tracing::warn!(
                            role = KNOWLEDGE_MCP_ROLE,
                            "gateway inventory lists no knowledge-base tools; using the default knowledge tool names"
                        );
                    }
                    knowledge_gateway_tool_names()
                } else {
                    discovered
                }
            } else {
                Vec::new()
            };
            ceilings.push(knowledge_ceiling_with_seed(row.enabled, seed));
        } else if row.role.as_deref() == Some(WEB_SEARCH_MCP_ROLE) {
            ceilings.push(web_search_ceiling(row.enabled, web_search_seed(&inventory)));
        }
    }
    Ok(ceilings)
}

/// Converge a literal tools allowlist onto one service ceiling: `enabled`
/// appends the seed (missing only, order kept); `!enabled` strips every
/// name under the prefix. A `*` wildcard means unrestricted and is left
/// alone either way. Returns whether anything changed.
pub fn reconcile_service_tools(tools: &mut Vec<String>, ceiling: &ServiceToolCeiling) -> bool {
    if tools.iter().any(|name| name == "*") {
        return false;
    }
    if ceiling.enabled {
        let mut changed = false;
        for name in &ceiling.seed {
            if !tools.contains(name) {
                tools.push(name.clone());
                changed = true;
            }
        }
        changed
    } else {
        let before = tools.len();
        tools.retain(|name| !name.starts_with(&ceiling.prefix));
        tools.len() != before
    }
}

/// Keep the `main` profile's literal tools allowlist in sync with the system
/// MCP servers and the knowledge service ceiling. The MCP reconcile mirrors
/// the server and its tools to the gateway, but an existing profile's
/// `tools` list is not part of that write; without this step the assistant
/// registers the tool yet never offers it.
///
/// Skips unmanaged user-created rows (`source: "local"` without our baseline
/// prompt), unrestricted lists (`tools` missing, or containing the gateway's
/// literal `*`), and rows that already carry every system tool. Returns
/// whether a config PUT was sent.
///
/// Lock-free by itself: the caller ([`ensure_default_assistant`] or the
/// service-MCP coordinator) holds the process-wide gateway-config lock
/// across this GET→PUT cycle and the one in [`converge_managed_profiles`].
pub(crate) async fn ensure_system_tools(
    client: &GatewayClient,
    ceilings: &[ServiceToolCeiling],
) -> Result<bool, GatewayError> {
    let profiles = client.get_json("/api/agents/config").await?;
    let profiles = profiles
        .as_array()
        .ok_or_else(|| GatewayError::Upstream("GET /api/agents/config returned a non-array document".to_owned()))?;
    let Some(index) = profiles.iter().position(|profile| {
        profile
            .get("id")
            .and_then(Value::as_str)
            .is_some_and(|id| id.eq_ignore_ascii_case(DEFAULT_ASSISTANT_AGENT_ID))
    }) else {
        return Ok(false);
    };
    let profile = &profiles[index];
    if !is_laifcore_managed_profile(profile) {
        return Ok(false);
    }
    let Some(tools) = profile.get("tools").and_then(Value::as_array) else {
        return Ok(false);
    };
    if tools.iter().any(|tool| tool.as_str() == Some("*")) {
        return Ok(false);
    }
    let mut names: Vec<String> = tools.iter().filter_map(Value::as_str).map(str::to_owned).collect();
    // The builtin web-search tools are replaced by the service-linked MCP
    // server in this product; a stale copy in main must not survive.
    let mut changed = remove_hidden_builtin_tools(&mut names);
    changed |= append_missing_system_tools(&mut names);
    for ceiling in ceilings {
        changed |= reconcile_service_tools(&mut names, ceiling);
    }
    if !changed {
        return Ok(false);
    }
    let mut next = profiles.clone();
    next[index]["tools"] = json!(names);
    client.put_json("/api/agents/config", Value::Array(next)).await?;
    tracing::info!(
        agent = DEFAULT_ASSISTANT_AGENT_ID,
        tools = names.len(),
        "main profile tools extended with system MCP tools"
    );
    Ok(true)
}

/// Converge EVERY managed profile's (see [`is_managed_profile`]) literal
/// tools list onto the knowledge service ceiling — `main` itself included
/// (idempotently after [`ensure_system_tools`]) plus the zone-pack rows
/// `normalize_profile` seeds. Wildcard or missing `tools` mean unrestricted
/// and are skipped. Returns whether a config PUT was sent.
///
/// Lock-free by itself: the caller holds the process-wide gateway-config
/// lock (see [`ensure_system_tools`]).
pub(crate) async fn converge_managed_profiles(
    client: &GatewayClient,
    ceilings: &[ServiceToolCeiling],
) -> Result<bool, GatewayError> {
    let profiles = client.get_json("/api/agents/config").await?;
    let Some(mut rows) = profiles.as_array().cloned() else {
        return Err(GatewayError::Upstream(
            "GET /api/agents/config returned a non-array document".to_owned(),
        ));
    };
    let mut converged = 0usize;
    for row in rows.iter_mut() {
        if !is_managed_profile(row) {
            continue;
        }
        let Some(tools) = row.get("tools").and_then(Value::as_array) else {
            continue;
        };
        let mut names: Vec<String> = tools.iter().filter_map(Value::as_str).map(str::to_owned).collect();
        let mut changed = false;
        for ceiling in ceilings {
            changed |= reconcile_service_tools(&mut names, ceiling);
        }
        if changed {
            row["tools"] = json!(names);
            converged += 1;
        }
    }
    if converged == 0 {
        return Ok(false);
    }
    client.put_json("/api/agents/config", Value::Array(rows)).await?;
    tracing::info!(
        services = ceilings.len(),
        profiles = converged,
        "managed agent profiles converged onto the service ceilings"
    );
    Ok(true)
}

/// Whether the profile is ours to keep complete: gateway-builtin rows, or a
/// `source: "local"` row that already references our baseline prompt (the
/// shape `seed_default_assistant` writes). A user-created `main` without the
/// baseline stays authoritative, so its tools list is never rewritten.
fn is_laifcore_managed_profile(profile: &Value) -> bool {
    if profile.get("source").and_then(Value::as_str) != Some("local") {
        return true;
    }
    profile
        .get("defaultSystemPrompt")
        .and_then(Value::as_array)
        .is_some_and(|entries| {
            entries
                .iter()
                .any(|entry| entry.get("file").and_then(Value::as_str) == Some(DEFAULT_PROMPT_FILE_NAME))
        })
}

/// Whether the profile's tools list is ours to converge onto the service
/// ceilings: every [`is_laifcore_managed_profile`] row plus zone-pack rows —
/// `source: "marketplace"` carrying the exact baseline entry shape
/// `normalize_profile` writes (`{ "file": "default.md", "enabled": true }`).
/// In practice the first term already claims every marketplace row (a
/// `marketplace` source only ever comes from our own pack landing), so the
/// second term documents the pack shape rather than widening the set; the
/// only rows that stay out are user-created `local` rows without our
/// baseline entry.
fn is_managed_profile(profile: &Value) -> bool {
    if is_laifcore_managed_profile(profile) {
        return true;
    }
    profile.get("source").and_then(Value::as_str) == Some("marketplace")
        && profile
            .get("defaultSystemPrompt")
            .and_then(Value::as_array)
            .is_some_and(|entries| {
                entries.iter().any(|entry| {
                    entry.get("file").and_then(Value::as_str) == Some(DEFAULT_PROMPT_FILE_NAME)
                        && entry.get("enabled").and_then(Value::as_bool) == Some(true)
                })
            })
}

