/* ============================================================
   团队工作区（team workspace）
   —— PaneFrame 骨架样式（自 feat/a2ui conversation/index.css 移植）
   + 团队三态骨架（tw- 前缀）。
   类名 tw- 前缀，勿与办公会话 .conv-workspace-col/.fp-float 混用。
   骨架类 .pane-frame 与组件（src/pages/conversation/pane/PaneFrame.tsx）
   一致。视觉 token 沿用 app.css 现有 CSS 变量。
   注意：tw- 三态骨架放在文件末尾——.tw-overlay 与 .workbench-overlay
   同特异性时靠后者声明在后的层叠序取 z-index 60。
   ============================================================ */

/* 统一面板框架 PaneFrame：顶部一行（左 tab 栏 + 右操作钮）+ 内容区。 */
.pane-frame {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
/* 顶部一行：上下 14 + 22px 图标钮 = 51px，与左侧聊天页头同高。 */
.pane-frame-head {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--border-soft);
  background: var(--bg-panel);
  /* 14 + 22 图标钮 + 1 底边 = 51，和左侧页头同高同节奏（22px 钮 / 4px 间距，
     图标中心与页头那排落在同一 y）。 */
  padding: 14px 12px;
  box-sizing: border-box;
}
/* 顶栏排列统一（规格 2026-11-07-pane-frame-icon-order）：内容钮居左、功能钮
   居右——任务页与欢迎页共用 PaneFrame 基础布局（tabs-row flex:1 居左、
   toolbar margin-left:auto 居右），无 .tw-col 排列特例。 */
/* 预览态：tab 留在左侧，文件名 + 预览控件由门户头铺满其余宽度。 */
.tw-col.tw-col-preview .pane-frame-head {
  justify-content: flex-start;
}
/* tabs 段：横排 tab 条带；浮窗拖动手柄在 head 整行（见下方 tw-float 光标）。 */
.pane-frame-tabs-row {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  align-self: stretch;
  overflow: hidden;
}
/* 溢出滚动：tab 标题放不下时条带横向滚动（滚动条隐藏），箭头步进见 PaneFrame。 */
.pane-frame-tabs-scroll {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.pane-frame-tabs-scroll::-webkit-scrollbar {
  display: none;
}
.pane-frame-tab-arrow {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 24px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-secondary);
  cursor: pointer;
}
.pane-frame-tab-arrow:hover:not(:disabled) {
  color: var(--text-primary);
}
.pane-frame-tab-arrow:disabled {
  opacity: 0.4;
  cursor: default;
}
/* tab 标签里的图标（如文件类型图标）。 */
.pane-frame-tab-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.pane-frame-tab-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  /* 溢出滚动下标签整体可见；病理长标题以省略号封顶，不把条带撑穿。 */
  max-width: 180px;
}
/* 操作钮区：靠右，无内容时塌成 0 宽。合并了 a2ui 的基态与工具条间距两条规则。 */
.pane-frame-toolbar {
  display: flex;
  margin-left: auto;
  justify-content: flex-end;
  gap: 4px;
  align-items: center;
  padding: 0;
}
.pane-frame-toolbar:empty {
  display: none;
}
.pane-frame-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
/* tab 栏在顶部一行内（head 的左段；溢出时条带横向滚动，trigger 不收缩）。 */
.pane-frame-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  min-width: 0;
}
/* 工作台多选切换 chev 钮（tab 触发器右侧兄弟）：同 22px 图标钮规格
   （规格 2026-11-07-pane-frame-icon-order §3）。 */
.pane-frame-tabs .pane-frame-tab-after-btn {
  width: 22px;
  height: 22px;
  margin: 0;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--text-tertiary);
  cursor: pointer;
}
.pane-frame-tabs .pane-frame-tab-after-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}
/* 顶栏 tab 与右侧状态钮同规格：22px 图标钮（图标 16），不做文字 tab。
   选择器要压过办公 Tabs 的 underline 变体（light 下 14px / padding 10px 4px）。 */
.pane-frame .ui-tabs[data-variant='underline'] .pane-frame-tabs .ui-tabs-trigger {
  width: 22px;
  height: 22px;
  margin: 0;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-bottom: 0;
  border-radius: 4px;
  color: var(--text-tertiary);
}
.pane-frame .ui-tabs[data-variant='underline'] .pane-frame-tabs .ui-tabs-trigger:hover:not([data-disabled]) {
  background: var(--bg-hover);
  color: var(--text-primary);
}
/* 选中态只用中性色：图标加深 + 很浅的灰底，和右侧状态钮同一套视觉，不用蓝色。 */
.pane-frame .ui-tabs[data-variant='underline'] .pane-frame-tabs .ui-tabs-trigger[data-state='active'] {
  background: var(--bg-hover);
  border-bottom-color: transparent;
  color: var(--text-primary);
}
.pane-frame .ui-tabs[data-variant='underline'] .pane-frame-tabs .ui-tabs-trigger[data-state='active']::after {
  content: none;
}
/* overlay：触发器浮在顶栏之下的内容区右上角，不占列宽。 */
.pane-frame-stage {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  cursor: grab;
  touch-action: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: max-content;
  margin: 0;
  padding: 4px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-panel) 55%, transparent);
  backdrop-filter: blur(8px);
}
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs .ui-tabs-trigger {
  width: 32px;
  height: 32px;
  margin: 0;
  padding: 0;
  border-bottom: 0;
  border-radius: 8px;
  opacity: 0.55;
  justify-content: center;
}
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs .ui-tabs-trigger:hover,
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs .ui-tabs-trigger[data-state='active'] {
  opacity: 1;
}
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs .ui-tabs-trigger[data-state='active'] {
  color: var(--accent);
  background: color-mix(in srgb, var(--bg-panel) 88%, transparent);
  border-bottom-color: transparent;
}
.pane-frame.pane-frame-tab-overlay .pane-frame-overlay-tabs .ui-tabs-trigger[data-state='active']::after {
  content: none;
}

/* 预览顶栏在正文里时让开右上角图标组。收进面板顶栏后不再让。 */
.pane-frame-tab-overlay .pane-frame-stage .fp-hd-r {
  margin-right: 36px;
}
.pane-frame-title-host {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
}
.pane-frame-title-host:empty {
  display: none;
  flex: 0 0 0;
}
/* 头已有 12px 内边距，嵌套 .fp-hd 不再叠一层，只去底边与底色。 */
.pane-frame-head .fp-hd {
  flex: 1;
  min-width: 0;
  border-bottom: 0;
  background: transparent;
  padding: 0;
}
/* 浮窗：标题行可拖，文件名区不抢选区；顶圆角对齐办公 .fp-float .fp-hd。 */

