//! Mirror a rotated SUP Admin-Token into knowledge-base MCP configs.
//!
//! The SSO service publishes the token only after it is durable. This task
//! updates every HTTP/SSE MCP row carrying an X-Admin-Token header, reloads
//! the already-connected LaifCode MCP transports in place, and refreshes the
//! pi-gateway copy. It never restarts a conversation: the pi tool registry is
//! left untouched and only the affected MCP server transports are swapped.

use aionui_api_types::SyncMcpToGatewayRequest;
use aionui_mcp::{GatewayMcpSyncService, GatewaySessionReloadMode, McpConfigService};
use aionui_sso::{AdminTokenUpdateSource, SsoService};
use tokio::sync::broadcast;
use tracing::{info, warn};

pub(crate) fn spawn_admin_token_mcp_sync(sso: SsoService, mcp: McpConfigService, gateway: GatewayMcpSyncService) {
    let mut updates = sso.subscribe_admin_token_updates();
    tokio::spawn(async move {
        loop {
            match updates.recv().await {
                Ok(update) => {
                    apply_admin_token(&mcp, &gateway, &update.token, Some(update.source)).await;
                }
                Err(broadcast::error::RecvError::Lagged(skipped)) => {
                    // The event is only a hint; the durable row is the source
                    // of truth. Re-read it instead of permanently skipping the
                    // rotation.
                    warn!(skipped, "admin token MCP sync lagged; re-reading the stored token");
                    if let Some(token) = sso.admin_token().await {
                        apply_admin_token(&mcp, &gateway, &token, None).await;
                    }
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    });
}

async fn apply_admin_token(
    mcp: &McpConfigService,
    gateway: &GatewayMcpSyncService,
    token: &str,
    source: Option<AdminTokenUpdateSource>,
) {
    let changed = match mcp.update_admin_token_headers(token).await {
        Ok(changed) => changed,
        Err(error) => {
            warn!(error = %error, "admin token MCP header update failed");
            return;
        }
    };
    if changed.is_empty() {
        return;
    }

    // Local sessions switch transports in place; the batch gateway mirror
    // runs once after this and never rebuilds a conversation.
    let reload = aionui_ai_agent::reload_all_mcp_admin_token(token).await;

    let ids: Vec<String> = changed.iter().map(|server| server.id.clone()).collect();
    let gateway_result = gateway
        .sync_definitions_to_gateway(SyncMcpToGatewayRequest {
            mcp_server_ids: ids,
            mcp_server_names: Vec::new(),
        })
        .await;
    match gateway_result {
        Ok(_) => {
            if let Err(error) = gateway.reload_sessions(GatewaySessionReloadMode::Graceful).await {
                warn!(error = %error, "admin token gateway session reload failed");
            }
        }
        Err(error) => {
            warn!(error = %error, "admin token gateway MCP sync failed");
        }
    }

    info!(
        source = ?source,
        changed = changed.len(),
        runtimes = reload.runtimes,
        reloaded = reload.reloaded,
        failed = reload.failed,
        "admin token MCP sync completed"
    );
}

