const [optionsError, setOptionsError] = useState<string | null>(null);
const [optionsTruncated, setOptionsTruncated] = useState(false);

const [pickerOpen, setPickerOpen] = useState(false);
const [activeAgentId, setActiveAgentId] = useState("");
const [query, setQuery] = useState("");

const loadBinding = useCallback(async () => {
	try {
		const res = await imApi.getWechatBinding();
		setBinding(res.binding);
		setBindingError(null);
	} catch (e) {
		setBindingError(e instanceof Error ? e.message : "读取绑定信息失败");
	} finally {
		setBindingLoading(false);
	}
}, []);

const loadOptions = useCallback(async () => {
	setOptionsLoading(true);
	let partial = false;
	try {
		const agents = await agentApi.listAgentSessions();

		const collected: ImSessionOption[] = [];
		const seen = new Set<string>();
		for (const agent of agents) {
			for (const session of agent.sessions) {
				if (seen.has(session.id)) continue;
				seen.add(session.id);
				collected.push({
					sessionId: session.id,
					title: session.title || session.id,
					agentId: agent.agentId,
					agentName: agent.name,
					updatedAt: session.createdAt,
				});
			}
		}

		collected.sort((a, b) => b.updatedAt - a.updatedAt);
		setKnownSessionIds(new Set(collected.map((o) => o.sessionId)));
		setIndexPartial(partial);
		setOptionsTruncated(collected.length > MAX_OPTIONS);
		setOptions(collected.slice(0, MAX_OPTIONS));
		setOptionsError(null);
	} catch (e) {
		setOptionsError(e instanceof Error ? e.message : "读取会话列表失败");
	} finally {
		setOptionsLoading(false);
	}
}, []);

useEffect(() => {
	void loadBinding();
	void loadOptions();
}, [loadBinding, loadOptions]);

const bindSession = async (sessionId: string) => {
	setSaving(true);
	setBindingError(null);
	try {
		const res = await imApi.putWechatBinding(sessionId);
		setBinding(res.binding);
		setPickerOpen(false);
		setQuery("");
		toast.success("已绑定会话");
	} catch (e) {
		toast.error(`绑定失败：${e instanceof Error ? e.message : String(e)}`);
	} finally {
		setSaving(false);
	}
};

const unbind = async () => {
	setSaving(true);
	setBindingError(null);
	try {
		await imApi.deleteWechatBinding();
		setBinding(null);
		toast.success("已解绑");
	} catch (e) {
		toast.error(`解绑失败：${e instanceof Error ? e.message : String(e)}`);
	} finally {
		setSaving(false);
	}
};

