	const word = text.trim().toLowerCase();
	const approved = APPROVE_WORDS.has(word) ? true : DENY_WORDS.has(word) ? false : null;
	if (approved === null) {
		// Never guess at an approval: ask again and do not consume the message
		// as a prompt either (that would silently lose it mid-decision).
		await this.#deps.send("没看懂。回复「批准」放行这一次，或「拒绝」。");
		return true;
	}
	this.#clear();
	await this.#invoke(pending.sessionId, "permission", {
		action: "confirm",
		requestId: pending.requestId,
		approved,
		remember: false,
	});
	await this.#deps.send(approved ? "已批准执行。" : "已拒绝执行。");
	return true;
}

