// im-wechat/interactions.ts — bridge the gateway's blocking interactions to chat.
//
// `permission:request` and `ask:question` hold the agent turn open until a client
// answers them. A chat-driven turn would otherwise sit there with no way to
// answer: the chat user only sees the "typing" receipt. Both are plain text here —
// the reply is matched against a small vocabulary and posted back through the same
// tool entry the web UI uses (gateway.invokeSessionTool).
//
// One interaction is tracked at a time: the bound session runs one turn at a time,
// and the gateway queues the rest.
//
// Reference: refs/dsh-im/src/channels/shared/harness-approval.mjs (text protocol,
// actor check, timeout → safe default, "cannot display it fully → deny").

import type { UiForwardPayload } from "../../core/events/types.ts";
import { createModuleLogger } from "../../core/logger.ts";

const log = createModuleLogger("im-wechat");

/** A permission request waits this long for a chat answer, then it is denied. */
const PERMISSION_TIMEOUT_MS = 30 * 60_000;

/** Reply words accepted for a permission request (trimmed, lowercased). */
const APPROVE_WORDS = new Set(["批准", "同意", "允许", "通过", "可以", "yes", "y", "ok", "1"]);
const DENY_WORDS = new Set(["拒绝", "不同意", "不允许", "不通过", "不行", "取消", "no", "n", "2"]);

interface QuestionOption {
	label: string;
	description: string;
}

interface QuestionData {
	id: string;
	question: string;
	header: string;
	options: QuestionOption[];
	multi?: boolean;
	recommended?: number;
}

interface QuestionAnswer {
	questionId: string;
	selectedLabels: string[];
	customInput?: string;
}

interface PermissionRequestData {
	requestId: string;
	toolName: string;
	command?: string;
	message: string;
	/** Present when a sub-agent's request bubbled up to this session. */
	subagentTitle?: string;
}

type Pending =
	| { kind: "permission"; sessionId: string; requestId: string; timer: ReturnType<typeof setTimeout> }
	| { kind: "ask"; sessionId: string; requestId: string; questions: QuestionData[] };

export interface InteractionBridgeDeps {
	/** Deliver a plain-text notice to the chat that started the turn. */
	send(text: string): Promise<void>;
	/** Invoke a tool inside a session (gateway.invokeSessionTool). */
	invokeTool(sessionId: string, toolName: string, params: unknown): Promise<void>;
}

export class InteractionBridge {
	readonly #deps: InteractionBridgeDeps;
	#pending: Pending | null = null;

	constructor(deps: InteractionBridgeDeps) {
		this.#deps = deps;
	}

	hasPending(): boolean {
		return this.#pending !== null;
	}

	/**
	 * React to one forwarded UI event. Only the two blocking kinds are handled;
	 * everything else on that channel is a plain notification.
	 */
	async handle(event: UiForwardPayload): Promise<void> {
		switch (event.customType) {
			case "permission:request":
				await this.#onPermissionRequest(event);
				return;
			case "ask:question":
				await this.#onAsk(event);
				return;
			case "permission:resolved":
			case "ask:question:resolved": {
				const requestId = (event.data as { requestId?: string } | undefined)?.requestId;
				// Only ours, and only when we did not resolve it ourselves: after a chat
				// answer this is the echo of our own invoke.
				if (this.#pending?.requestId === requestId) {
					this.#clear();
					await this.#deps.send("这条请求已经在别处处理了，无需再回复。");
				}
				return;
			}
			default:
				return;
		}
	}

	/**
	 * Try to read `text` as the answer to the pending interaction.
	 * Returns true when the reply was consumed (including a rejection of the
	 * format), false when there is nothing pending.
	 */
	async tryAnswer(text: string): Promise<boolean> {
		const pending = this.#pending;
		if (!pending) return false;
		if (pending.kind === "permission") return await this.#answerPermission(pending, text);
		return await this.#answerQuestion(pending, text);
	}

	/** Drop any pending interaction (polling stopped, binding cleared, …). */
	clear(): void {
		this.#clear();
	}

	// -------------------------------------------------------------------------
	// permission
	// -------------------------------------------------------------------------

	async #onPermissionRequest(event: UiForwardPayload): Promise<void> {
		const data = event.data as PermissionRequestData | undefined;
		if (!data?.requestId) return;
		// A newer request supersedes the old one: the previous turn is already gone.
		this.#clear();
		const timer = setTimeout(() => {
			void this.#onPermissionTimeout(data.requestId);
		}, PERMISSION_TIMEOUT_MS);
		timer.unref();
		this.#pending = { kind: "permission", sessionId: event.sessionId ?? "", requestId: data.requestId, timer };

		const who = data.subagentTitle ? `[${data.subagentTitle}] ` : "";
		await this.#deps.send(
			[
				`⚠️ ${who}需要你确认：`,
				data.message,
				"",
				"回复「批准」或「拒绝」。超过 30 分钟未回复将按拒绝处理。",
			].join("\n"),
		);
	}

	async #answerPermission(pending: Pending & { kind: "permission" }, text: string): Promise<boolean> {
		const word = text.trim().toLowerCase();
		const approved = APPROVE_WORDS.has(word) ? true : DENY_WORDS.has(word) ? false : null;
		if (approved === null) {
			// Never guess at an approval: ask again and do not consume the message
			// as a prompt either (that would silently lose it mid-decision).
			await this.#deps.send("没看懂。回复「批准」放行这一次，或「拒绝」。");
			return true;
		}
		this.#clear();
		await this.#invoke(pending.sessionId, "permission", {
			action: "confirm",
			requestId: pending.requestId,
			approved,
			remember: false,
		});
		await this.#deps.send(approved ? "已批准执行。" : "已拒绝执行。");
		return true;
	}

	async #onPermissionTimeout(requestId: string): Promise<void> {
		const pending = this.#pending;
		if (pending?.kind !== "permission" || pending.requestId !== requestId) return;
		this.#clear();
		// Safe default: an unanswered approval is a denial, never a silent grant.
		await this.#invoke(pending.sessionId, "permission", {
			action: "confirm",
			requestId,
			approved: false,
			remember: false,
		});
		await this.#deps.send("这个确认请求超时了，已按拒绝处理。");
	}

	// -------------------------------------------------------------------------
	// ask_user_question
	// -------------------------------------------------------------------------

	async #onAsk(event: UiForwardPayload): Promise<void> {
		const data = event.data as { requestId?: string; questions?: QuestionData[] } | undefined;
		const questions = data?.questions ?? [];
		if (!data?.requestId || questions.length === 0) return;
		const timer = this.#pending?.kind === "permission" ? this.#pending.timer : null;
		if (timer) clearTimeout(timer);
		this.#pending = { kind: "ask", sessionId: event.sessionId ?? "", requestId: data.requestId, questions };
		await this.#deps.send(renderQuestions(questions));
	}

	async #answerQuestion(pending: Pending & { kind: "ask" }, text: string): Promise<boolean> {
		const lines = text
			.split(/\r?\n/)
			.map((line) => line.trim())
			.filter(Boolean);
		if (lines.length === 0) {
			await this.#deps.send("请回一个选项编号，或直接写下你的答案。");
			return true;
		}
		const answers: QuestionAnswer[] = [];
		for (const [index, question] of pending.questions.entries()) {
			// One line per question, in order; a single-question ask is just one line.
			const line = lines[index];
			if (line === undefined) break;
			answers.push(answerFor(question, line));
		}
		this.#clear();
		await this.#invoke(pending.sessionId, "ask_user_question", {
			action: "answer",
			requestId: pending.requestId,
			answers,
		});
		await this.#deps.send(`已回复：${answers.map((a) => describeAnswer(a)).join("；")}`);
		return true;
	}

	// -------------------------------------------------------------------------

	async #invoke(sessionId: string, toolName: string, params: unknown): Promise<void> {
		if (!sessionId) return;
		try {
			await this.#deps.invokeTool(sessionId, toolName, params);
		} catch (error) {
			log.error("Failed to answer a chat interaction", {
				toolName,
				error: error instanceof Error ? error.message : String(error),
			});
			await this.#deps.send("回填答案失败了，会话可能已经结束。");
		}
	}

	#clear(): void {
		if (this.#pending?.kind === "permission") clearTimeout(this.#pending.timer);
		this.#pending = null;
	}
}

// ---------------------------------------------------------------------------
// Rendering / parsing helpers
// ---------------------------------------------------------------------------

function renderQuestions(questions: QuestionData[]): string {
	const blocks = questions.map((question, qIndex) => {
		const title = questions.length > 1 ? `${qIndex + 1}. ${question.question}` : question.question;
		const options = question.options.map((option, oIndex) => {
			const recommended = question.recommended === oIndex ? "（推荐）" : "";
			return `  ${oIndex + 1}. ${option.label}${recommended} — ${option.description}`;
		});
		return [title, ...options].join("\n");
	});
	const hint =
		questions.length > 1
			? "按顺序一行回一个：第一行答第一题，回复编号或直接写答案。"
			: "回复选项编号，或直接写下你的答案。";
	return ["❓ 需要你确认：", ...blocks, "", hint].join("\n");
}

/** Parse one reply line against one question. Unmatched text becomes free input. */
function answerFor(question: QuestionData, line: string): QuestionAnswer {
	const tokens = question.multi ? line.split(/[,，、\s]+/).filter(Boolean) : [line];
	const selected: string[] = [];
	const free: string[] = [];
	for (const token of tokens) {
		const byIndex = /^\d+$/.test(token) ? question.options[Number(token) - 1] : undefined;
		if (byIndex) {
			selected.push(byIndex.label);
			continue;
		}
		const byLabel = question.options.find((option) => option.label.toLowerCase() === token.toLowerCase());
		if (byLabel) {
			selected.push(byLabel.label);
			continue;
		}
		free.push(token);
	}
	const answer: QuestionAnswer = { questionId: question.id, selectedLabels: selected };
	if (free.length > 0) answer.customInput = free.join(" ");
	return answer;
}

function describeAnswer(answer: QuestionAnswer): string {
	if (answer.customInput) return answer.customInput;
	return answer.selectedLabels.length > 0 ? answer.selectedLabels.join("、") : "(未回答)";
}

