import type {
  AskQuestionMode,
  JsonValue,
  ProviderWithModel,
  QuestionData,
  QuestionResolution,
} from '@/shared/api/conversation';
import type { ModelSelection } from '@/pages/settings/models/model-utils';

export type PlanStepView = {
  id: string;
  title: string;
  status: 'done' | 'running' | 'pending';
  elapsed?: string;
  roundIds?: string[];
};
export type ArtifactView = {
  id: string;
  name: string;
  kind: 'xlsx' | 'md' | 'doc';
  size: string;
  size_bytes?: number;
  status: string;
  /** 该条目的来源判据：本地 diff 写 `create`/`modify`/`delete`，网关标记写 `marked`/`missing`。 */
  operation?: string;
  path?: string;
  turnId?: string;
};

// conversation 级 UI artifact 和 turn 级 artifact 分开建模。
// ArtifactView[] 表示某个 turn 内的文件变更；这里表示定时任务触发等会话级卡片。
export type ConversationArtifactView = {
  id: string;
  conversationId: string;
  kind: 'cron_trigger';
  status: string;
  createdAt: number;
  updatedAt?: number;
  cronJobId: string;
  cronJobName: string;
  triggeredAt: number;
  rawPayload?: unknown;
};

/**
 * 推荐产物条目视图（会话视图的 recommendedArtifacts[]）。
 * 由 runtime 从 kind='recommended_artifacts' 的产物行 map 出来，
 * rank 已按后端给定的展示顺序排好。
 */
export type RecommendedArtifactView = {
  id: string;
  name: string;
  kind: string;
  size: string;
  sizeBytes?: number;
  rank: number;
  reason?: string;
  source: 'heuristic' | 'llm';
  path: string;
};

export type ToolView = { id: string; name: string; scope: string };
export type UsageView = { id: string; label: string; value: string };

/**
 * 会话级上下文用量快照（tokens）。
 *
 * 每个来源（WS `acp_context_usage` 流事件 / GET usage 快照）都是对同一状态的
 * 幂等覆盖，一轮内多次到达合法（输入守卫压缩 + 轮次结束各一次），绝不累加。
 */
export type ContextUsageView = {
  used: number;
  total: number;
  remaining: number;
  cached?: number | null;
};

export type RoundMemberView = {
  ref: string;
  kind: 'text' | 'thinking' | 'tool_call';
};

export type RoundTranscriptView = {
  id: string;
  taskId: string;
  seq: number;
  title: string;
  status: 'running' | 'done' | 'error';
  planStepId?: string;
  todoEntryId?: string;
  startedAt: number;
  endedAt?: number;
  durationMs?: number;
  members: RoundMemberView[];
  summary: {
    text?: string;
    actions: Array<{ kind: string; count: number }>;
    files: Array<{ path: string; op: string; additions?: number; deletions?: number }>;
    skill?: { name: string };
  };
};

export type TaskSummaryView = {
  taskId: string;
  title: string;
  status: 'running' | 'completed' | 'error';
  roundCount: number;
  topLevelRoundIds: string[];
  durationMs?: number;
};

export type MessageView = {
  id: string;
  role: 'user' | 'assistant';
  type?:
    | 'text'
    | 'tips'
    | 'tool_call'
    | 'tool_call_progress'
    | 'tool_group'
    | 'agent_status'
    | 'acp_permission'
    | 'plan'
    | 'thinking'
    | 'ask'
    | 'ask_user_question';
  content: string;
  ts: string;
  createdAt?: number;
  thinking?: boolean;
  tool?: string;
  summary?: string;
  detail?: string;
  command?: string;
  plan?: PlanStepView[];
  status?: string;
  tone?: 'success' | 'warning' | 'error' | 'info';
  subject?: string;
  conversationId?: string;
  msgId?: string;
  turnId?: string;
  roundId?: string;
  callId?: string;
  rawContent?: unknown;
  /** 团队成员转述拷贝（wire `content.teammate_message === true`）：频道投影据此识别转述行。 */
  teammateMessage?: boolean;
  /** 工作台动作生成的用户消息（wire `content.workbench_message === true`）：气泡上方显示「工作台」来源标签。 */
  workbenchMessage?: boolean;
  /** ask_user_question 的 request_id（历史行与 WS 事件共用稳定消息 ID `ask-{request_id}`）。 */
  requestId?: string;
  /**
   * 交互卡是否可作答。
   *
   * 只由 GET pending 列表建立（含 WS ask 事件的乐观登记，随后以服务端列表校准）：
   * 历史行的 status / resolution 一律不参与判断。客户端 expires_at 只是 UX 提示，
   * 服务端始终是权威 —— 提交收到 409 时也必须把卡片翻成不可作答。
   */
  isPending?: boolean;
  questions?: QuestionData[];
  questionMode?: AskQuestionMode;
  /** 行上的终态（answered / cancelled / timeout），仅用于只读展示。 */
  questionResolution?: QuestionResolution | null;
  /**
   * 提问的过期时刻（Unix ms），来自历史行 content / WS 事件 / pending 列表。
   *
   * 只用于展示（无终态但已过期 → 显示「过期」而不是「不可用」）：可作答性
   * 仍然只认服务端，客户端时钟只是提示。
   */
  expiresAt?: number;
};

export type ThreadBlockView =
  | {
      id: string;
      type: 'user_message';
      role: 'user';
      createdAt: number;
      messageIds: [string];
    }
  | {
      id: string;
      type: 'assistant_message';
      role: 'assistant';
      createdAt: number;
      messageIds: string[];
      turnId?: string;
    }
  | {
      id: string;
      type: 'round';
      role: 'assistant';
      createdAt: number;
      roundId: string;
      turnId?: string;
      messageIds: string[];
    }
  | {
      id: string;
      type: 'conversation_artifact';
      role: 'assistant';
      createdAt: number;
      artifactId: string;
    };

export type ConversationView = {
  id: string;
  title: string;
  status: 'pending' | 'running' | 'finished';
  /** laifcore 瞬态（现场拼接，非持久 status；gateway_session_id 仅 ACP 有值） */
  runtime?: import('@/shared/api/conversation').ConversationRuntimeSummary | null;
  extra: JsonValue;
  /** 会话顶层 source（'assistant' = 主助理哨兵，见 assistantMode）；runtime 装配不保证恒有。 */
  source?: import('@/shared/api/conversation').ConversationResponse['source'];
  /** 显示名（basename，见 getWorkspaceName）；fs 接口的沙箱根一律用 getWorkspaceRoot()。 */
  workspace: string;
  startedAt: string;
  elapsed: string;
  messages: MessageView[];
  rounds: RoundTranscriptView[];
  threadBlocks: ThreadBlockView[];
  taskSummary?: TaskSummaryView;
  todos: PlanStepView[];
  artifacts: ArtifactView[];
  conversationArtifacts: ConversationArtifactView[];
  /** 推荐产物（kind='recommended_artifacts' 行 map 出的视图，rank 已排序）。 */
  recommendedArtifacts: RecommendedArtifactView[];
  tools: ToolView[];
  usage: UsageView[];
  contextUsage?: ContextUsageView | null;
  /** 专家切换的后台摘要仍在途（register→WS 终态事件之间）：相关动作置灰用。 */
  expertSummaryPending?: boolean;
  /** 专家配置应用仍在途（apply-expert→WS 终态事件之间）：composer 相关按钮置灰用（见 UiConversation）。 */
  profileApplyPending?: boolean;
  modelLabel: string;
  model?: ProviderWithModel | null;
  /** auto 模型最近一次解析结果（extra.resolved_model）：Auto 选项回显用。 */
  resolvedModel?: ModelSelection | null;
  activeMsgId?: string | null;
  activeTurnId?: string | null;
  /** 网关正在重试本轮（attempt 从 1 开始）：pending 行显示「正在重试 n/N」。 */
  retryHint?: { attempt: number; maxAttempts: number } | null;
  /** Observed wall-clock end time per turn (see UiConversation). */
  turnEndedAtById?: Record<string, number>;
  lastEventAt?: number;
};

export type ThreadItem =
  | { id: string; role: 'user'; message: MessageView }
  | { id: string; role: 'assistant'; messages: MessageView[] };

